# Twin of t237 ((n-1)! -> (n-2)!): for non-prime n >= 1, (n-2)! = 0 mod n iff n != 4
# (natural-number subtraction, so n = 1, 2 give 0! = 1). Proof: if n = ab with 1 < a < b then a, b <= n/2 <= n-2;
# if n = q^2 with q >= 3 prime then q < 2q <= n-2, so q*2q | (n-2)!; n = 4 gives 2! = 2. Exhaustive check below.
import math
def is_prime(n):
    return n >= 2 and all(n % d for d in range(2, int(math.isqrt(n)) + 1))
exceptions = []
for n in range(1, 3001):
    if is_prime(n):
        continue
    if math.factorial(max(n - 2, 0)) % n != 0:
        exceptions.append(n)
# the defect case of D' (n = 0 allowed): x = y [MOD 0] means x = y, and (0-2)! = 0! = 1 != 0, so D' fails at n = 0
print("D' holds at n = 0:", math.factorial(0) == 0)
print(",".join(map(str, exceptions)))

# Twin of t259 (f(1) = 1 -> f(2) = 2): the twin reduces to the original by g(x) = f(2x)/2, which is smooth, nonnegative,
# g(0) = 0 and g(1) = 1, with g^(n)(x) = 2^(n-1) f^(n)(2x); so g^(n)(x) < 0 gives f^(n)(2x) < 0 with the same n >= 1.
# The script checks the scaling identity exactly on random rational polynomials (n = 0..6) and prints True.
import random
from fractions import Fraction as F
random.seed(20261012)
def deriv(c):
    return [i * c[i] for i in range(1, len(c))]
def ev(c, x):
    return sum(ci * x ** i for i, ci in enumerate(c))
ok = True
for _ in range(200):
    f = [F(random.randint(-9, 9), random.randint(1, 9)) for _ in range(8)]
    g = [f[i] * F(2) ** i / 2 for i in range(len(f))]        # g(x) = f(2x)/2
    fd, gd = f[:], g[:]
    for n in range(7):
        x = F(random.randint(-20, 20), random.randint(1, 7))
        if ev(gd, x) != F(2) ** n / 2 * ev(fd, 2 * x):
            ok = False
        fd, gd = deriv(fd), deriv(gd)
    if ev(g, F(0)) != ev(f, F(0)) / 2 or ev(g, F(1)) != ev(f, F(2)) / 2:
        ok = False
print(ok)
